#[test]
fn unicode_common_script_results_snapshot() {
    let mut rows = String::new();
    for name in ["Script=Common", "Script=Zyyy", "sc=Common", "sc=Zyyy"] {
        for body in [
            format!(r"\p{{{name}}}"),
            format!(r"\P{{{name}}}"),
            format!(r"(?<x>[\p{{{name}}}K])"),
        ] {
            let pattern = JsString::from(body.as_str());
            for flags in ["dug", "diug", "divg", "divy"] {
                for input in ["µΜμ0Σ😀\n", "X\r\n0\u{2028}א", ""] {
                    let input = JsString::from(input);
                    for start in [0, 1, 3] {
                        let script = format!(
                            "let r=new RegExp({pattern:?},{flags:?});r.lastIndex={start};let m=r.exec({input:?});JSON.stringify({{m,index:m?.index,groups:m?.groups,indices:m?.indices,indexGroups:m?.indices?.groups,lastIndex:r.lastIndex,source:r.source}})"
                        );
                        let Value::String(result) = Realm::default().eval(&script).unwrap() else {
                            panic!("{script}")
                        };
                        writeln!(
                            rows,
                            "{body:?} flags={flags:?} input={input:?} lastIndex={start} {result:?}"
                        )
                        .unwrap();
                    }
                }
            }
        }
    }
    insta::assert_snapshot!(rows);
}
#[test]
fn unicode_common_script_captures_context_and_pair_starts() {
    for mode in ["u", "v"] {
        check(&format!(
            r"let r=/^(?<x>([\p{{sc=Zyyy}}K]))$/dim{mode}g,m=r.exec('A\r\n0\u2028');m.index===3&&m[1]==='0'&&m[2]==='0'&&m.indices.groups.x===m.indices[1]&&m.indices[2][1]===4&&r.lastIndex===4"
        ));
        check(&format!(
            r"let r=/(?<__proto__>\p{{Script=Common}})/d{mode}y;r.lastIndex=1;let m=r.exec('😀A');m.index===0&&m[1]==='😀'&&m.indices[1][1]===2&&r.lastIndex===2&&Object.getPrototypeOf(m.groups)===null&&m.indices.groups.__proto__===m.indices[1]"
        ));
        check(&format!(
            r"let r=/\P{{sc=Common}}/d{mode}g;r.lastIndex=1;let m=r.exec('😀\uD800');m.index===2&&m[0]==='\uD800'&&r.lastIndex===3"
        ));
        check(&format!(
            r"let r=/\P{{Script=Zyyy}}/{mode}y;r.lastIndex=1;r.exec('😀\uD800')===null&&r.lastIndex===0"
        ));
    }
}

#[test]
fn unicode_common_script_consumers_preserve_original_text() {
    for mode in ["u", "v"] {
        check(&format!(
            r"let a=[...'0😀A1'.matchAll(/(?<x>\P{{sc=Common}})/d{mode}g)];a.length===1&&a[0][1]==='A'&&a[0].index===3&&a[0].indices[1][1]===4"
        ));
        check(&format!(
            r"'01A'.replace(/(?<x>\p{{sc=Zyyy}})/{mode}g,'<$1:$<x>>')==='<0:0><1:1>A'"
        ));
        check(&format!(
            r"'A01A'.split(/(\p{{Script=Common}})/{mode}).join('|')==='A|0||1|A'&&'Aא0'.search(/\p{{sc=Zyyy}}/{mode})===2&&'01A'.match(/\p{{Script=Zyyy}}/{mode}g).join('')==='01'"
        ));
        check(&format!(
            r"let t='',x='01A0'.replace(/(\p{{sc=Common}})/{mode}g,(m,c,p)=>{{t+=p;return '_'}});x==='__A_'&&t==='013'"
        ));
    }
}

#[test]
fn unicode_common_script_clones_coercions_and_strict_writes() {
    check(
        r"let r=/^(?<x>\p{sc=Zyyy})$/dmu,c=new RegExp(r,'divy');c.source==='^(?<x>\\p{sc=Zyyy})$'&&c.unicodeSets&&!c.unicode&&!c.multiline&&c.exec('0').groups.x==='0'&&c.lastIndex===1",
    );
    check(
        r"let t='',r=/\p{Script=Common}/uy;r.lastIndex={valueOf(){t+='i';return 1}};let m=r.exec({toString(){t+='s';return '😀'}});t==='si'&&m[0]==='😀'&&m.index===0&&r.lastIndex===2",
    );
    check(
        r"let r=/\p{sc=Common}/vy;Object.defineProperty(r,'lastIndex',{writable:false});let caught=false;try{r.exec('0')}catch(e){caught=e instanceof TypeError}caught&&r.lastIndex===0",
    );
    check(
        r"let r=/\P{Script=Zyyy}/vy;r.lastIndex=1;Object.defineProperty(r,'lastIndex',{writable:false});let caught=false;try{r.exec('😀\uD800')}catch(e){caught=e instanceof TypeError}caught&&r.lastIndex===1",
    );
}

#[test]
fn unicode_common_script_repeated_sources_captures_and_collection() {
    assert_eq!(Limits::default().max_steps, None);
    assert_eq!(Limits::default().max_heap_entries, None);
    let mut realm = Realm::default();
    realm.eval("let p='^'+'('.repeat(3000)+'['+'\\\\p{sc=Zyyy}\\\\p{Cs}\\\\p{ASCII}'.repeat(10000)+']'+')'.repeat(3000)+'$',r=new RegExp(p,'dmvg'),c=new RegExp(r),text='A'.repeat(100000)+'\\n0'").unwrap();
    realm.collect(usize::MAX).unwrap();
    assert_eq!(realm.eval("let m=c.exec(text);m.length===3001&&m[1]==='0'&&m[3000]==='0'&&m.indices[3000][0]===100001&&m.indices[3000][1]===100002&&c.lastIndex===100002"), Ok(Value::Boolean(true)));
    realm.eval("p=null;r=null;c=null;text=null;m=null").unwrap();
    realm.collect(usize::MAX).unwrap();
}

#[test]
fn unicode_common_script_opted_work_and_remaining_sets() {
    let mut realm = Realm::new(Limits {
        max_steps: Some(30000),
        ..Limits::default()
    });
    realm
        .eval("let r=/\\p{Script=Common}/ug,marker=0,text='A'.repeat(10000);r.lastIndex=1")
        .unwrap();
    assert!(matches!(
        realm.eval("try{r.exec(text)}catch{marker=1}finally{marker=2}"),
        Err(Error::Limit { .. })
    ));
    assert_eq!(
        realm.eval("marker===0&&r.lastIndex===1"),
        Ok(Value::Boolean(true))
    );
    check(r"/\p{Script_Extensions=Common}/u.exec('A')===null");
    for source in [
        r"/[\p{sc=Zyyy}&&A]/v.exec('A')",
        r"/[\p{sc=Zyyy}--A]/v.exec('A')",
        r"/\p{sc=Zyyy}+b/u.exec('AA')",
        r"/\p{sc=Zyyy}A/v.exec('AA')",
    ] {
        assert!(
            matches!(
                Realm::default().eval(source),
                Err(Error::Unsupported { .. })
            ),
            "{source}"
        );
    }
}

#[test]
fn unicode_common_script_repetitions_retain_last_capture_and_outside_words() {
    for mode in ["u", "v"] {
        check(&format!(
            r"let r=/\B(?<x>\p{{sc=Zyyy}})+\B/d{mode}g,m=r.exec('א😀😀😀א');m.index===1&&m[0]==='😀😀😀'&&m.groups.x==='😀'&&m.indices.groups.x[0]===5&&m.indices.groups.x[1]===7&&r.lastIndex===7"
        ));
    }
}

